var modeNames = {
	1: "朗读模式",
	3: "小说模式",
	2: "听书模式",
	8: "漫画模式",
	11: "短剧配套模式",
	12: "短剧内置模式",
	13: "短剧洛娅模式"

};










// 设置保存接口
function set(num) {
	if (source.getVariable()=="") {

    reg(true);
}
    if (num < 0 || num >= data.length) {
        java.longToast("无效的接口编号！");
        return;
    }
    var show = "设置成功\n当前模式：";
    var tips = "\n‼️设置完成请点击切换模式‼️"
    var setData = JSON.parse(source.getVariable())

    const currentTone = data[num][1];
    if (currentTone === "0" ) {
        setData.module = 2;
    } else {
        setData.module = 1;
    }

    setData.sz = num.toString();
    setData.tone = currentTone;
    source.setVariable(JSON.stringify(setData, null, "\t"));

    var currentMode = setData.module || 1;
    var msg = show + (modeNames[currentMode] || "未知模式") + 
              "\n音色设置：" + data[num][0] + tips;
    java.longToast(msg);
}


// 获取接口显示
function get() {
	if (source.getVariable()=="") {
    reg(true);
    try {
        var v = JSON.parse(source.getVariable() || "{}");
        var currentMode = v.module || 1;

        var message = "当前模式：/n" + (modeNames[currentMode] || "未知模式");

        if (currentMode === 2) {
            var sz = parseInt(v.sz || "0", 10);
            var toneName = (sz >= 0 && sz < data.length) ? data[sz][0] : "默认";
            message += "\n音色设置：" + toneName;
        }

        java.longToast(message);
    } catch (e) {
        java.longToast("获取模式失败：" + e.message);
    }
}else{
    try {
        var v = JSON.parse(source.getVariable() || "{}");
        var currentMode = v.module || 3;

        var message = "\n当前模式：" + (modeNames[currentMode] || "未知模式");

        if (currentMode === 2) {
            var sz = parseInt(v.sz || "0", 10);
            var toneName = (sz >= 0 && sz < data.length) ? data[sz][0] : "默认";
            message += "\n音色设置：" + toneName;
        }

        java.longToast(message);
    } catch (e) {
        java.longToast("获取模式失败：" + e.message);
    }}
}










function st() {


    var v = JSON.parse(source.getVariable());
    var mode = v.module|| 3; 






    var newMode;
    if (mode === 1) {
        newMode = 3;
    } else
    if (mode === 3) {
        newMode = 2;
    } else

     if (mode === 2) {
        newMode = 8;
    } else

     if (mode === 8) {
        newMode = 11;
    } else

     if (mode === 11) {
        newMode = 12;
    } else

     if (mode === 12) {
        newMode = 13;
    } else


     if (mode === 13) {
        newMode = 1;
    } else {
        newMode = 3; 
    }


    v.module = newMode;


    v.sz = "0";
    v.tone = "";

    source.setVariable(JSON.stringify(v, null, "\t"));

    var show = "设置成功\n当前模式：";
    var tips = "\n请前往详情页刷新是否切换成功";



    var msg;

    if (newMode === 1) {
        msg = show + "朗读模式" + tips
    } else 


    if (newMode === 3) {
        msg = show + "阅读模式" + tips
    } else 

    if (newMode === 2) {
    	   msg = show + "听书模式" + tips;
    } else

     if (newMode === 8){
        msg = show + "漫画模式" + tips;
    } else 
     if (newMode === 11){
        msg = show + "短剧配套模式" + tips;
    } else 
     if (newMode === 12){
        msg = show + "短剧内置模式" + tips;
    } else 

    if (newMode === 13) {
        msg = show + "短剧洛娅模式" + tips;
    }

    java.longToast(msg);
}

