    '小说-红楼': '链接',
    '小说-乐播':'链接'
};
var apiGroups = {
    '影视-常规': ['影视-如意', '影视-无水印', '影视-红牛', '影视-豪华', '影视-速播', '影视-索尼', '影视-量子', '影视-暴风', '影视-360', '影视-魔都'],
    '影视-18禁': ['影视-香蕉', '影视-细胞', '影视-番号', '影视-极品', '影视-奥斯卡', '影视-搜V资源', '影视-黑料', '影视-杏吧', '影视-红楼','影视-乐播'],
    '小说与图集': ['小说-jkun', '小说-155','小说-杏吧','小说-红楼','小说-乐播']
};
var vars = {};
try { vars = JSON.parse(source.getVariable()); } catch (e) { vars = { group: '影视-常规', api: '影视-如意', url: apiMap['影视-如意'] }; }
var currentGroup = vars.group || '影视-常规';
var currentApi = vars.api || '影视-如意';
if (apiGroups[currentGroup].indexOf(currentApi) === -1) { currentApi = apiGroups[currentGroup][0]; }
var base = apiMap[currentApi] || apiMap['影视-如意'];
var isArt = base.indexOf('/art/') !== -1;

var actionChange = "var map=" + JSON.stringify(apiMap) + "; var g=infoMap['接口类型']||'影视-常规'; var a=infoMap['接口选择']||'影视-如意'; var u=map[a]; source.setVariable(JSON.stringify({group:g, api:a, url:u})); java.toast('切换成功，正在加载引擎...'); java.refreshExplore();";

var ui = [];
ui.push({ title: '接口类型', type: 'select', chars: Object.keys(apiGroups), default: currentGroup, action: actionChange, style: { layout_flexBasisPercent: 1 } });
ui.push({ title: '接口选择', type: 'select', chars: apiGroups[currentGroup], default: currentApi, action: actionChange, style: { layout_flexBasisPercent: 1 } });
ui.push({ title: '全局关键字', type: 'text', default: '', style: { layout_flexBasisPercent: 1 } });
ui.push({ title: '🔍 当前接口搜', type: 'button', action: "var k = infoMap['全局关键字']; if(!k){ java.toast('输入为空'); } else { java.searchBook(k, source); }", style: { layout_flexBasisPercent: 1 } });

var rawCats = [];
var parentMap = {};
try {
    var jsonStr = java.ajax(base + '?ac=list&at=json');
    rawCats = JSON.parse(jsonStr).class || [];
    for (var i = 0; i < rawCats.length; i++) { parentMap[rawCats[i].type_id] = rawCats[i].type_name; }
} catch (e) {}

var ignoreIds = [1, 2, 3, 4];
var seen = {};
for (var i = 0; i < rawCats.length; i++) {
    var c = rawCats[i];
    if (!c.type_id || !c.type_name || ignoreIds.indexOf(parseInt(c.type_id, 10)) !== -1 || seen[c.type_id]) continue;
    seen[c.type_id] = true;
    var pName = parentMap[c.type_pid] || '';
    var name = pName && pName !== c.type_name ? pName + '-' + c.type_name : c.type_name;
    ui.push({ title: name, url: base + '?ac=' + (isArt ? 'list' : 'videolist') + '&t=' + c.type_id + '&pg={{page}}&at=json', style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.31 } });
}
